initial_condition:
with {
    the SUT being in the "initial state" and
    the SUT contains a Context Source Registration 
        with id equal to ${context_source_registration_id}
        and payload set to ${context_source_registration_payload_file_path}
}

test_cases.then:
then {
    the SUT sends a valid Response for the operations:
        Update Context Source Registration With Return with Response Status Code set to 405     and
        Update Context Source Registration With Return with Response reason set to 'Method Not Allowed'     and
        Update Context Source Registration With Return with Response does not contain a body
}

test_cases.when:
when {
    the SUT receives a Request from the client containing:
        URL set to '/ngsi-ld/v1/csourceRegistrations/{registration_id}'
        method set to 'PATCH'
        Update Context Source Registration with id set to '${EMPTY}' and registration update fragment set to '${fragment_with_id}' and content-type set to 'application/ld+json'
}
